import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"端到端测试套件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/e2e-suites.md","filePath":"zh/dev/e2e-suites.md"}'),n={name:"zh/dev/e2e-suites.md"};function i(l,e,c,r,p,d){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="端到端测试套件" tabindex="-1">端到端测试套件 <a class="header-anchor" href="#端到端测试套件" aria-label="Permalink to &quot;端到端测试套件&quot;">​</a></h1><p>用于发布门禁的深度测试。所有测试都通过 pexpect 在串口控制台上驱动真实的 QEMU 启动过程。</p><h2 id="回归测试套件-tools-run-fix4-regression-py" tabindex="-1">回归测试套件 - tools/run_fix4_regression.py <a class="header-anchor" href="#回归测试套件-tools-run-fix4-regression-py" aria-label="Permalink to &quot;回归测试套件 - tools/run_fix4_regression.py&quot;">​</a></h2><p>28 项检查：启动横幅、启动完成、异常自测 3/3、命令计数 233、uname 标签格式、heaptest、fstest、cryptotest、crashlog、l1test，以及所有 <code>run &lt;userprog&gt;</code>（hello、fork、exec、pipe、signal、select、mmap 变体、动态链接：so_test、dlsym_test、pie_test、reloc_test、p3、g6、g7...）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><h2 id="看门狗-日志-健康-e2e-tools-wp12-watchdog-logging-e2e-py" tabindex="-1">看门狗/日志/健康 E2E - tools/wp12_watchdog_logging_e2e.py <a class="header-anchor" href="#看门狗-日志-健康-e2e-tools-wp12-watchdog-logging-e2e-py" aria-label="Permalink to &quot;看门狗/日志/健康 E2E - tools/wp12_watchdog_logging_e2e.py&quot;">​</a></h2><p>14 个场景（S1-S14）。其中最重要的两个：</p><ul><li><strong>S12（Intel TCO）</strong>：q35 + <code>-no-reboot</code>；断言 TCO 发现行（<code>Intel TCO found: PMBASE=... TCOBASE=...</code>）、启用看门狗、使其饥饿、断言真实复位和第二次启动。</li><li><strong>S13（ACPI WDAT）</strong>：通过 WDAT 表条目以相同方式实现。</li></ul><p>此外还有 klog 写入/刷新/轮转/过滤链（阈值 4096 -&gt; <code>kernel.log</code> + <code>kernel.log.1</code> 实际生成）、看门狗策略终止（一个饥饿任务被终止并记录日志，而内核存活）、以及健康监控（JSON 导出有效性、3 个旋转的 CPU 警报 <code>CPU-LOCKED</code> 且内核存活）。</p><h2 id="ssh-e2e" tabindex="-1">SSH E2E <a class="header-anchor" href="#ssh-e2e" aria-label="Permalink to &quot;SSH E2E&quot;">​</a></h2><p>客户机内的 <code>sshd</code> 需要在 /etc 卷上拥有主机/客户端密钥 - 测试套件（或您）使用 <code>host_keygen_etc</code> 对它们进行初始化。然后来自主机的 paramiko 客户端执行完整的登录 + 会话 + 命令往返：5/5 全部通过即为门禁。</p><h2 id="https-e2e" tabindex="-1">HTTPS E2E <a class="header-anchor" href="#https-e2e" aria-label="Permalink to &quot;HTTPS E2E&quot;">​</a></h2><p>客户机内部使用 <code>wget https://&lt;reference-host&gt;/</code> 访问参考 TLS 服务器：握手成功、收到 GET、正文保存、close_notify 清晰。7 项检查（握手、证书链、正文字节、关闭语义、计时）。</p><h2 id="etc-卷固件" tabindex="-1">/etc 卷固件 <a class="header-anchor" href="#etc-卷固件" aria-label="Permalink to &quot;/etc 卷固件&quot;">​</a></h2><p>SSH 和 HTTPS 套件假定已初始化的 <code>etc.img</code>。每个测试周期构建一次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make etc.img          # 32 MiB FAT32 + opencube.conf</span></span>
<span class="line"><span># then inside a first boot: host_keygen_etc (writes SSH keys)</span></span></code></pre></div><p>QEMU 的 <code>run-*</code> make 目标会自动附加它。</p>`,17)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
